import json, time, urllib.request, urllib.error, sys
from datetime import datetime, timezone

BASE = "http://localhost:8080"
START = datetime(2025, 3, 1, tzinfo=timezone.utc)
END = datetime(2025, 6, 1, tzinfo=timezone.utc)  # exclusive: 31 May inclusive

log = open("/tmp/recon/log.txt", "w")
def note(*a):
    s = " ".join(str(x) for x in a)
    log.write(s + "\n"); log.flush()

def raw(method, path, token=None):
    req = urllib.request.Request(BASE + path, method=method)
    if token:
        req.add_header("Authorization", "Bearer " + token)
    try:
        with urllib.request.urlopen(req, timeout=30) as r:
            return r.status, dict(r.headers), r.read().decode()
    except urllib.error.HTTPError as e:
        return e.code, dict(e.headers), e.read().decode(errors="replace")

token = None
def get_token():
    global token
    while True:
        st, h, body = raw("POST", "/token")
        if st == 200:
            token = json.loads(body)["token"]
            note("token acquired")
            return
        note("token failed", st, body[:200]); time.sleep(1)

def authed_get(path):
    """GET with retries: refresh token on 401, sleep on 429, retry others."""
    attempts = 0
    while True:
        attempts += 1
        if token is None:
            get_token()
        st, h, body = raw("GET", path, token)
        if st == 200:
            return json.loads(body)
        if st == 401:
            note("401 on", path, "- refreshing token")
            get_token(); continue
        if st == 429:
            wait = h.get("Retry-After")
            note("429 on", path, "Retry-After=", wait, "body=", body[:200])
            try:
                secs = float(wait)
            except (TypeError, ValueError):
                secs = 2.0
            time.sleep(secs + 0.5); continue
        if st == 404:
            return None
        note("HTTP", st, "on", path, body[:200], "attempt", attempts)
        if attempts > 50:
            sys.exit("giving up on " + path)
        time.sleep(min(2 ** attempts, 30))

# Pass 1: walk every page, following total_pages.
seen = {}          # id -> first order record
listings = 0
dupes = 0
page = 1
total_pages = None
while True:
    data = authed_get(f"/orders?page={page}")
    if total_pages is None:
        total_pages = data["total_pages"]; note("total_pages", total_pages)
    for o in data["items"]:
        listings += 1
        if o["id"] in seen:
            dupes += 1
            if seen[o["id"]] != o:
                note("DIFFERENT duplicate content for", o["id"], seen[o["id"]], o)
        else:
            seen[o["id"]] = o
    note("page", page, "items", len(data["items"]), "next", data.get("next"))
    if page >= total_pages:
        break
    page += 1

note("listings", listings, "distinct", len(seen), "dupes", dupes)

# Pass 2: filter.
qual = []
for o in seen.values():
    ts = datetime.fromisoformat(o["placed_at"].replace("Z", "+00:00")).astimezone(timezone.utc)
    if o["status"] == "shipped" and START <= ts < END:
        qual.append(o)
note("qualifying", len(qual))

# Pass 3: customers, cached.
cust = {}
for o in qual:
    cid = o["customer_id"]
    if cid not in cust:
        cust[cid] = authed_get(f"/customers/{cid}")
missing = [c for c, v in cust.items() if v is None]
note("customers fetched", len(cust), "missing", missing)

# Discount: amount * (100 - pct) / 100, rounded half up per order, integer arithmetic.
by_region = {"north": 0, "south": 0, "east": 0, "west": 0}
total = 0
for o in qual:
    c = cust[o["customer_id"]]
    if c is None:
        note("skipping order with unknown customer", o["id"]); continue
    num = o["amount_cents"] * (100 - c["discount_pct"])
    q, r = divmod(num, 100)
    if 2 * r >= 100:
        q += 1
    by_region[c["region"]] += q
    total += q

result = {
    "total_cents": total,
    "order_count": len(qual),
    "duplicates_skipped": dupes,
    "by_region": by_region,
}
note(json.dumps(result))
json.dump(result, open("/tmp/recon/result.json", "w"), indent=2)
print(json.dumps(result, indent=2))
EOF
cd /tmp/recon && timeout 550 python3 -I collect.py; echo "exit $?"; echo ---; grep -E "429|HTTP|401|DIFFERENT|missing|total_pages|listings|qualifying" /tmp/recon/log.txt | head -40

